def count_duplicates(items):
    duplicates = 0
    for i in range(len(items)):
        for j in range(len(items)):
            if i != j and items[i] == items[j]:
                duplicates += 1
    return duplicates // 2

items.solution_code:
def count_duplicates(items):
    seen = {}
    for item in items:
        seen[item] = seen.get(item, 0) + 1
    duplicates = 0
    for count in seen.values():
        duplicates += count * (count - 1) // 2
    return duplicates
